def urljoin_(base, url):
    """
    RFC 3986 URL reference resolution.
    """
    def split_url(s):
        """Split a URL into (scheme, authority, path, query, fragment)."""
        s = s.strip()
        if not s:
            return None, None, '', None, None

        scheme = None
        authority = None
        path = ''
        query = None
        fragment = None

        # Remove fragment
        if '#' in s:
            s, fragment = s.split('#', 1)

        # Remove query
        if '?' in s:
            s, query = s.split('?', 1)

        # Check for scheme
        scheme_match = None
        for i, c in enumerate(s):
            if c == ':':
                # Check if it looks like a scheme (letters, digits, +, -, . before :)
                prefix = s[:i]
                if prefix and (prefix[0].isalpha() or prefix[0] == '_'):
                    valid = True
                    for ch in prefix[1:]:
                        if not (ch.isalnum() or ch in '+-.'):
                            valid = False
                            break
                    if valid:
                        scheme = prefix
                        s = s[i+1:]
                        break

        # Check for authority
        if s.startswith('//'):
            s = s[2:]
            # Authority ends at first /, ?, or # (but ? and # already removed)
            end = s.find('/')
            if end == -1:
                authority = s
                s = ''
            else:
                authority = s[:end]
                s = s[end:]

        # Remaining is path
        path = s

        return scheme, authority, path, query, fragment

    def remove_dot_segments(path):
        """Remove . and .. segments from a path per RFC 3986."""
        output = []
        # Split path into segments, preserving empty segments
        # We need to handle leading / properly
        segments = path.split('/')
        # Reconstruct: the first element is '' if path starts with /
        # Process segments
        for seg in segments:
            if seg == '.':
                continue
            elif seg == '..':
                if output:
                    output.pop()
            else:
                output.append(seg)
        # Rejoin
        return '/'.join(output)

    def merge_paths(base_path, ref_path):
        """Merge base path and reference path per RFC 3986."""
        if base_path:
            # Remove last segment from base path
            idx = base_path.rfind('/')
            if idx == -1:
                base_path = ''
            else:
                base_path = base_path[:idx + 1]
        return base_path + ref_path

    # Split base and url
    base_scheme, base_auth, base_path, base_query, base_frag = split_url(base)
    ref_scheme, ref_auth, ref_path, ref_query, ref_frag = split_url(url)

    # If reference has a scheme, it's an absolute URL
    if ref_scheme is not None:
        # Resolve reference as-is
        result_scheme = ref_scheme
        result_auth = ref_auth
        result_path = remove_dot_segments(ref_path) if ref_path else ref_path
        result_query = ref_query
        result_frag = ref_frag
    else:
        # Use base's scheme and authority
        result_scheme = base_scheme
        result_auth = ref_auth if ref_auth is not None else base_auth

        if ref_path == '':
            # Path is empty
            result_path = base_path
            # If reference has query, use it; else keep base query
            result_query = ref_query if ref_query is not None else base_query
        else:
            if ref_path.startswith('/'):
                # Absolute path
                result_path = remove_dot_segments(ref_path)
                result_query = ref_query
            else:
                # Relative path
                result_path = remove_dot_segments(merge_paths(base_path, ref_path))
                result_query = ref_query
        result_frag = ref_frag

    # Build result
    result = ''
    if result_scheme is not None:
        result += result_scheme + ':'
    if result_auth is not None:
        result += '//' + result_auth
    if result_path is not None:
        result += result_path
    if result_query is not None:
        result += '?' + result_query
    if result_frag is not None:
        result += '#' + result_frag

    return result
