def urljoin_(base, url):
    """
    Reproduce urllib.parse.urljoin from scratch per RFC 3986.
    """
    def parse_url(url):
        """Parse URL into components: scheme, netloc, path, query, fragment"""
        scheme = None
        netloc = None
        path = ''
        query = None
        fragment = None

        # Check for scheme
        if ':' in url:
            # Find the first colon that indicates a scheme
            # Scheme must be at the beginning
            i = url.find(':')
            # Verify it's a valid scheme (alphanumeric, +, -, .)
            potential_scheme = url[:i]
            if potential_scheme and all(
                c.isalnum() or c in '+-.' for c in potential_scheme
            ):
                scheme = potential_scheme
                url = url[i + 1:]

        # Check for netloc
        if url.startswith('//'):
            url = url[2:]
            # Find end of netloc
            end = 0
            for i, c in enumerate(url):
                if c in '/?#' :
                    end = i
                    break
            else:
                end = len(url)
            netloc = url[:end]
            url = url[end:]

        # Check for fragment
        if '#' in url:
            idx = url.find('#')
            fragment = url[idx + 1:]
            url = url[:idx]

        # Check for query
        if '?' in url:
            idx = url.find('?')
            query = url[idx + 1:]
            url = url[:idx]

        # Remaining is path
        path = url

        return scheme, netloc, path, query, fragment

    def remove_dot_segments(path):
        """
        Remove dot segments from a path per RFC 3986 section 5.2.4
        """
        # Split path into segments
        if path.startswith('/'):
            leading_slash = True
            path = path[1:]
        else:
            leading_slash = False

        if path == '':
            segments = []
        else:
            segments = path.split('/')

        output = []
        for segment in segments:
            if segment == '.':
                continue
            elif segment == '..':
                if output:
                    output.pop()
            else:
                output.append(segment)

        if leading_slash:
            return '/' + '/'.join(output)
        else:
            return '/'.join(output)

    # Parse both URLs
    base_scheme, base_netloc, base_path, base_query, base_fragment = parse_url(base)
    url_scheme, url_netloc, url_path, url_query, url_fragment = parse_url(url)

    # If the reference has a scheme, it replaces the base
    if url_scheme is not None:
        # Reference is absolute
        if url_netloc:
            result_path = url_path
            result_netloc = url_netloc
            result_scheme = url_scheme
        else:
            # Scheme present but no netloc
            result_path = url_path
            result_netloc = None
            result_scheme = url_scheme
    else:
        # No scheme in reference
        if url_netloc:
            # Scheme-relative reference: //host/path
            result_scheme = base_scheme
            result_netloc = url_netloc
            result_path = url_path
        else:
            # Relative reference
            result_scheme = base_scheme
            result_netloc = base_netloc
            if url_path == '':
                # Empty path
                if url_query is not None:
                    # Query-only reference
                    result_path = base_path
                    result_query = url_query
                elif url_fragment is not None:
                    # Fragment-only reference
                    result_path = base_path
                    result_query = base_query
                else:
                    # Empty reference: return base without fragment
                    result_path = base_path
                    result_query = base_query
                # Handle fragment
                if url_fragment is not None:
                    result_fragment = url_fragment
                else:
                    result_fragment = None
                # Build result
                result = ''
                if result_scheme:
                    result += result_scheme + ':'
                if result_netloc:
                    result += '//' + result_netloc
                result += result_path
                if result_query is not None:
                    result += '?' + result_query
                if result_fragment is not None:
                    result += '#' + result_fragment
                return result
            else:
                # Non-empty path
                if url_path.startswith('/'):
                    # Absolute path
                    result_path = url_path
                else:
                    # Relative path: merge with base path
                    # Take base path up to last slash
                    if base_path.rfind('/') >= 0:
                        base_dir = base_path[:base_path.rfind('/') + 1]
                    else:
                        base_dir = ''
                    result_path = base_dir + url_path
                # Merge query
                if url_query is not None:
                    result_query = url_query
                else:
                    result_query = base_query
                # Merge fragment
                if url_fragment is not None:
                    result_fragment = url_fragment
                else:
                    result_fragment = base_fragment
                # Normalize path
                result_path = remove_dot_segments(result_path)
                # Build result
                result = ''
                if result_scheme:
                    result += result_scheme + ':'
                if result_netloc:
                    result += '//' + result_netloc
                result += result_path
                if result_query is not None:
                    result += '?' + result_query
                if result_fragment is not None:
                    result += '#' + result_fragment
                return result
        # If we reached here with url_netloc set, handle it
        if url_netloc:
            result_query = url_query
            result_fragment = url_fragment
            result_path = remove_dot_segments(result_path) if result_path else ''
            result = ''
            if result_scheme:
                result += result_scheme + ':'
            if result_netloc:
                result += '//' + result_netloc
            result += result_path
            if result_query is not None:
                result += '?' + result_query
            if result_fragment is not None:
                result += '#' + result_fragment
            return result
    # If we reached here with url_scheme set
    if url_scheme is not None:
        result_query = url_query
        result_fragment = url_fragment
        result_path = remove_dot_segments(result_path) if result_path else ''
        result = ''
        if result_scheme:
            result += result_scheme + ':'
        if result_netloc:
            result += '//' + result_netloc
        result += result_path
        if result_query is not None:
            result += '?' + result_query
        if result_fragment is not None:
            result += '#' + result_fragment
        return result
    return base
